import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { registerGitHubTools } from "./github/tools/index.js";
import { createExpressApp } from "./server/app.js";

// Create an MCP server
const server = new McpServer({
  name: "GitHub MCP Server",
  version: "1.0.0",
});

// Register all GitHub tools
registerGitHubTools(server);

// Create and start the Express app
const app = createExpressApp(server);

// Start the server
const port = process.env.PORT || 8080;
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

import express from "express";
import type { Express } from "express";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { setupTransport, getTransport } from "./transport.js";

export function createExpressApp(server: McpServer): Express {
  const app = express();

  // SSE endpoint
  app.get("/sse", async (req, res) => {
    const transport = setupTransport(res);
    await server.connect(transport);
  });

  // Message endpoint
  app.post("/messages", async (req, res) => {
    const transport = getTransport();
    if (!transport) {
      res.status(400).json({ error: "No transport" });
      return;
    }
    await transport.handlePostMessage(req, res);
  });

  return app;
}

import type { Response } from "express";
import { SSEServerTransport } from "@modelcontextprotocol/sdk/server/sse.js";

let transport: SSEServerTransport | undefined = undefined;

export function setupTransport(res: Response) {
  transport = new SSEServerTransport("/messages", res);
  return transport;
}

export function getTransport() {
  return transport;
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import * as github from "../functions/index.js";

export function registerIssueTools(server: McpServer) {
  // Get an issue by number
  server.tool(
    "getIssue",
    "Get an issue by number",
    { owner: z.string(), repo: z.string(), issueNumber: z.number() },
    async ({ owner, repo, issueNumber }) => {
      const issue = await github.getIssue(owner, repo, issueNumber);
      return {
        content: [{ type: "text", text: JSON.stringify(issue, null, 2) }],
      };
    }
  );

  // Create a comment on an issue
  server.tool(
    "createIssueComment",
    "Create a comment on an issue",
    {
      owner: z.string(),
      repo: z.string(),
      issueNumber: z.number(),
      body: z.string(),
    },
    async ({ owner, repo, issueNumber, body }) => {
      const comment = await github.createIssueComment(
        owner,
        repo,
        issueNumber,
        body
      );
      return {
        content: [{ type: "text", text: JSON.stringify(comment, null, 2) }],
      };
    }
  );

  // Update an issue
  server.tool(
    "updateIssue",
    "Update an issue",
    {
      owner: z.string(),
      repo: z.string(),
      issueNumber: z.number(),
      updateData: z.object({
        title: z.string().optional(),
        body: z.string().optional(),
        state: z.enum(["open", "closed"]).optional(),
        labels: z.array(z.string()).optional(),
        assignees: z.array(z.string()).optional(),
      }),
    },
    async ({ owner, repo, issueNumber, updateData }) => {
      const issue = await github.updateIssue(
        owner,
        repo,
        issueNumber,
        updateData
      );
      return {
        content: [{ type: "text", text: JSON.stringify(issue, null, 2) }],
      };
    }
  );

  // List issues for a repository
  server.tool(
    "listIssues",
    "List issues for a repository",
    {
      owner: z.string(),
      repo: z.string(),
      options: z
        .object({
          state: z.enum(["open", "closed", "all"]).optional(),
          sort: z.enum(["created", "updated", "comments"]).optional(),
          direction: z.enum(["asc", "desc"]).optional(),
          per_page: z.number().optional(),
          page: z.number().optional(),
        })
        .optional(),
    },
    async ({ owner, repo, options }) => {
      const issues = await github.listIssues(owner, repo, options || {});
      return {
        content: [{ type: "text", text: JSON.stringify(issues, null, 2) }],
      };
    }
  );
}

export * from "./issues.js";
export * from "./pulls.js";
export * from "./actions.js";

import { Octokit } from "octokit";

const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });

// Get a pull request by number
export async function getPullRequest(
  owner: string,
  repo: string,
  pullNumber: number
) {
  const response = await octokit.rest.pulls.get({
    owner,
    repo,
    pull_number: pullNumber,
  });
  return response.data;
}

// Create a comment on a pull request
export async function createPullRequestComment(
  owner: string,
  repo: string,
  pullNumber: number,
  body: string
) {
  const response = await octokit.rest.issues.createComment({
    owner,
    repo,
    issue_number: pullNumber,
    body,
  });
  return response.data;
}

// Update a pull request
export async function updatePullRequest(
  owner: string,
  repo: string,
  pullNumber: number,
  updateData: {
    title?: string;
    body?: string;
    state?: "open" | "closed";
    base?: string;
  }
) {
  const response = await octokit.rest.pulls.update({
    owner,
    repo,
    pull_number: pullNumber,
    ...updateData,
  });
  return response.data;
}

// List pull requests for a repository
export async function listPullRequests(
  owner: string,
  repo: string,
  options: {
    state?: "open" | "closed" | "all";
    sort?: "created" | "updated" | "popularity" | "long-running";
    direction?: "asc" | "desc";
    per_page?: number;
    page?: number;
  } = {}
) {
  const response = await octokit.rest.pulls.list({
    owner,
    repo,
    ...options,
  });
  return response.data;
}

